import { Bot, Database, FlaskConical, Library, ShieldAlert, SlidersHorizontal } from "lucide-react";
import { REFERENCE_CONFIG, formatRange } from "@/config/reference-ranges";
import { NASA_RESOURCE, TEAM_BRIEF_ASSUMPTIONS, isResourceConfirmed } from "@/config/scientific-sources";
import { SCENARIO_ORDER, SCENARIOS } from "@/lib/scenarios";
import { VITAL_KEYS } from "@/lib/types";
import { Badge, Panel } from "@/components/ui/primitives";

const LIMITATIONS = [
  "All vital-sign data is synthetic and generated by a seeded script. It does not come from any person, mission or NASA dataset.",
  "Reference ranges, caution bands and sensor rules are provisional placeholders chosen by the development team. They have not been validated clinically or against a NASA resource.",
  "The analysis engine is deterministic and rule-based. It produces attention levels and data-reliability scores, never a diagnosis.",
  "Procedures are illustrative safety checklists. They are not approved flight procedures and never include medication, treatment or clinical interventions.",
  "Escalation rules only indicate when to involve the Crew Medical Officer and the ground flight surgeon. They are demonstration rules.",
  "The Earth–Mars link is a simulation. The 3–22 min one-way range is a simplification from the team brief; real delay depends on planetary geometry and the link can be unavailable (e.g. near solar conjunction).",
  "Ground acknowledgements are automatic placeholders. No real person reviews any message.",
  "Only three scripted scenarios are covered. Real sensors exhibit many other artifacts and real physiology many other patterns.",
  "The prototype has no authentication, persistence, encryption or medical-device quality controls.",
];

export function ScienceView() {
  const confirmed = isResourceConfirmed();
  const field = (v: string | null) => v ?? <span className="text-level-caution">pending team confirmation</span>;
  return (
    <div className="flex flex-col gap-4">
      <div>
        <p className="font-mono text-xs uppercase tracking-[0.2em] text-accent">Transparency</p>
        <h1 className="text-2xl font-semibold text-ink">Science, sources &amp; limitations</h1>
      </div>

      <div className="grid grid-cols-1 gap-4 xl:grid-cols-2">
        <Panel
          title="NASA scientific resource"
          eyebrow="Registry"
          icon={Library}
          tone={confirmed ? "nominal" : "caution"}
          actions={<Badge tone={confirmed ? "nominal" : "caution"}>{confirmed ? "Confirmed" : "Pending confirmation"}</Badge>}
        >
          <p className="text-sm text-ink-muted">
            The architecture is ready to integrate one real NASA scientific resource. Team ANGARIS will confirm the official challenge
            statement and the resource before the analysis rules are finalised. Until then no NASA data, source or result is claimed.
          </p>
          <dl className="mt-3 grid grid-cols-1 gap-2 text-sm sm:grid-cols-2" data-testid="nasa-resource">
            <div><dt className="text-[10px] uppercase tracking-[0.16em] text-ink-faint">Name</dt><dd>{field(NASA_RESOURCE.name)}</dd></div>
            <div><dt className="text-[10px] uppercase tracking-[0.16em] text-ink-faint">Origin</dt><dd>{field(NASA_RESOURCE.origin)}</dd></div>
            <div><dt className="text-[10px] uppercase tracking-[0.16em] text-ink-faint">URL / DOI</dt><dd className="break-all">{field(NASA_RESOURCE.url)}</dd></div>
            <div><dt className="text-[10px] uppercase tracking-[0.16em] text-ink-faint">Version · accessed</dt><dd>{field(NASA_RESOURCE.version && NASA_RESOURCE.accessedOn ? `${NASA_RESOURCE.version} · ${NASA_RESOURCE.accessedOn}` : null)}</dd></div>
            <div className="sm:col-span-2"><dt className="text-[10px] uppercase tracking-[0.16em] text-ink-faint">Effective use in the app</dt><dd>{field(NASA_RESOURCE.effectiveUse)}</dd></div>
          </dl>
          <h3 className="mt-4 text-xs font-semibold uppercase tracking-[0.16em] text-ink-faint">Integration points</h3>
          <ul className="mt-1 list-disc space-y-0.5 pl-5 font-mono text-[11px] text-ink-muted">
            {NASA_RESOURCE.integrationPoints.map((p) => (
              <li key={p}>{p}</li>
            ))}
          </ul>
          <h3 className="mt-4 text-xs font-semibold uppercase tracking-[0.16em] text-ink-faint">Values taken from the team brief</h3>
          <ul className="mt-1 space-y-1 text-sm text-ink-muted">
            {TEAM_BRIEF_ASSUMPTIONS.map((a) => (
              <li key={a.topic}>
                <span className="text-ink">{a.topic}:</span> {a.value} <span className="text-ink-faint">— {a.origin}</span>
              </li>
            ))}
          </ul>
        </Panel>

        <Panel title="Scientific limitations" eyebrow="Read before the demo" icon={ShieldAlert} tone="warning">
          <ul className="list-disc space-y-1.5 pl-5 text-sm text-ink-muted">
            {LIMITATIONS.map((l) => (
              <li key={l}>{l}</li>
            ))}
          </ul>
        </Panel>
      </div>

      <Panel
        title="Demo reference ranges and sensor rules"
        eyebrow={REFERENCE_CONFIG.status}
        icon={SlidersHorizontal}
        tone="caution"
        actions={<Badge tone="caution">{REFERENCE_CONFIG.status}</Badge>}
      >
        <p className="mb-3 text-sm text-level-caution">{REFERENCE_CONFIG.provenance}</p>
        <div className="overflow-x-auto">
          <table className="w-full min-w-[640px] text-left text-sm">
            <thead className="text-[10px] uppercase tracking-[0.14em] text-ink-faint">
              <tr>
                <th className="py-2 pr-3">Vital sign</th>
                <th className="py-2 pr-3">Demo reference</th>
                <th className="py-2 pr-3">Caution band</th>
                <th className="py-2 pr-3">Plausibility limits</th>
                <th className="py-2 pr-3">Max step / sample</th>
                <th className="py-2">Simulated sensor</th>
              </tr>
            </thead>
            <tbody className="tabular font-mono text-xs text-ink-muted">
              {VITAL_KEYS.map((k) => {
                const v = REFERENCE_CONFIG.vitals[k];
                return (
                  <tr key={k} className="border-t border-line/60">
                    <td className="py-2 pr-3 font-sans text-sm text-ink">{v.label}</td>
                    <td className="py-2 pr-3">{formatRange(k, v.normal)}</td>
                    <td className="py-2 pr-3">{formatRange(k, v.caution)}</td>
                    <td className="py-2 pr-3">{formatRange(k, v.plausible)}</td>
                    <td className="py-2 pr-3">
                      {v.maxStepDelta} {v.unit}
                    </td>
                    <td className="py-2 font-sans">{v.sensorName}</td>
                  </tr>
                );
              })}
            </tbody>
          </table>
        </div>
        <p className="mt-3 text-xs text-ink-faint">
          Persistence: {REFERENCE_CONFIG.persistenceSamples} samples · sensor look-back: {REFERENCE_CONFIG.sensorLookbackSamples} samples ·
          degraded quality &lt; {REFERENCE_CONFIG.degradedQuality * 100} % · poor quality &lt; {REFERENCE_CONFIG.poorQuality * 100} %. Edit
          in <code className="text-ink-muted">src/config/reference-ranges.ts</code>.
        </p>
      </Panel>

      <div className="grid grid-cols-1 gap-4 xl:grid-cols-2">
        <Panel title="Simulated data provenance" eyebrow="Demonstration scenarios" icon={Database}>
          <ul className="space-y-2 text-sm">
            {SCENARIO_ORDER.map((id) => {
              const s = SCENARIOS[id];
              return (
                <li key={id} className="rounded-md border border-line bg-space-850/60 p-3">
                  <p className="font-medium text-ink">{s.name}</p>
                  <p className="mt-0.5 text-xs text-ink-muted">{s.description}</p>
                  <p className="mt-1 font-mono text-[10px] text-ink-faint">
                    {s.samples.length} samples · {s.sampleIntervalSec} s interval · {s.generator.script} · seed {s.generator.seed}
                  </p>
                </li>
              );
            })}
          </ul>
        </Panel>

        <Panel title="AI assistance disclosure" eyebrow="Transparency" icon={Bot}>
          <div className="space-y-2 text-sm text-ink-muted">
            <p>
              This prototype&apos;s source code, simulated-data generator, demonstration procedures, interface text and documentation were
              produced with the help of an AI coding assistant (Claude Code, by Anthropic) working from the Team ANGARIS brief.
            </p>
            <p>
              The team is responsible for reviewing all AI-assisted content, confirming the scientific statement and NASA resource, and
              validating every rule before any claim is made. See <code>AI_DISCLOSURE.md</code> in the repository.
            </p>
            <p className="flex items-center gap-2 text-xs text-ink-faint">
              <FlaskConical className="h-4 w-4" /> No AI model runs inside the application: all analysis is deterministic.
            </p>
          </div>
        </Panel>
      </div>
    </div>
  );
}
